import numpy as np, wave, os, math, json, base64
os.makedirs('/workspace/samples',exist_ok=True)
sr=8363

def wav(name,x):
 x=np.clip(x,-1,1); y=(x*32767).astype('<i2')
 with wave.open('/workspace/samples/'+name,'wb') as f:
  f.setnchannels(1);f.setsampwidth(2);f.setframerate(sr);f.writeframes(y.tobytes())

def tone(name,kind,dur=.55):
 t=np.arange(int(sr*dur))/sr
 f=261.63
 if kind=='lead':
  ph=2*np.pi*f*t; x=np.sign(np.sin(ph))*.72 + .12*np.sin(2*ph)+.08*np.sin(3*ph); env=np.exp(-4.8*t)
 elif kind=='bass':
  ph=2*np.pi*f*t; x=2*(ph/(2*np.pi)%1)-1; x=.8*x+.2*np.sin(ph*2); env=np.exp(-5.5*t)
 elif kind=='pad':
  x=sum(np.sin(2*np.pi*f*k*t+q) for k,q in [(1,0),(2,.2),(3,.4)])/2.2; env=np.minimum(1,t/.025)*np.exp(-2.8*t)
 elif kind=='counter':
  x=np.sign(np.sin(2*np.pi*f*t))*.6+np.sin(2*np.pi*f*2*t)*.25; env=np.exp(-7*t)
 wav(name,x*env*.55)

def drum(name,typ,dur):
 t=np.arange(int(sr*dur))/sr
 if typ=='kick':
  ph=2*np.pi*(110*t+(-70)*(1-np.exp(-18*t))/18); x=np.sin(ph)*np.exp(-10*t)+.25*np.sin(2*ph)*np.exp(-18*t)
 elif typ=='snare':
  rng=np.random.default_rng(4); x=rng.normal(0,1,len(t))*np.exp(-20*t)+.25*np.sin(2*np.pi*180*t)*np.exp(-14*t)
 else:
  rng=np.random.default_rng(9); x=rng.normal(0,1,len(t))*np.exp(-35*t)
 wav(name,x*.48)
for n,k in [('lead.wav','lead'),('bass.wav','bass'),('pad.wav','pad'),('counter.wav','counter')]: tone(n,k)
drum('kick.wav','kick',.28);drum('snare.wav','snare',.22);drum('hat.wav','hat',.10)
