import json
calls=[]
# pattern lengths/orders
for p in range(6):
 calls.append({'name':'pattern_set_length','arguments':{'pattern':p,'rows':64}})
 calls.append({'name':'order_set','arguments':{'position':p,'pattern':p}})
# midi to note
def nt(n):
 names=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']; return names[n%12]+str(n//12-1)
def cell(p,r,ch,n=None,i=None,v=None):
 a={'pattern':p,'row':r,'channel':ch}
 if n is not None:a['note']=nt(n)
 if i is not None:a['instrument']=i
 if v is not None:a['volume']=v
 calls.append({'name':'pattern_set_cell','arguments':a})
roots=[50,46,41,48,43,45] # D3 Bb2 F2 C3 G2 A2
# chord tones
for p,root in enumerate(roots):
 # lead motifs in 2-row eighths, 4 bars, motifs around root
 scale=[0,2,3,5,7,10,12,14]
 motif=[[7,5,3,5,7,10,7,5],[0,3,5,7,5,3,0,-2],[7,10,12,10,7,5,3,5]][p%3]
 for bar in range(4):
  trans=(bar%2)*2
  for j,x in enumerate(motif):
   r=bar*16+j*2
   cell(p,r,0,root+12+x+trans,1,55 if j%4 else 62)
 # counter answers on offbeats
 for bar in range(4):
  for j,x in enumerate([0,3,5,3]): cell(p,bar*16+8+j*2,7,root+ x,4,42)
 # bass pulse every beat, octave lower, fifth alternating
 for bar in range(4):
  for beat in range(4): cell(p,bar*16+beat*4,2,root-12+(7 if beat==2 else 0),2,58)
 # pad chord each bar, major/minor coloring
 minor=p in [0,4,5]
 third=3 if minor else 4
 for bar in range(4):
  r=bar*16; cell(p,r,3,root,3,34);cell(p,r,3,root+third,3,30);cell(p,r,3,root+7,3,30)
 # drums
