 for r in range(8,64,16): cell(p,r,5,38,6,52)
 for r in range(12,64,16): cell(p,r,5,38,6,42)
 for r in range(2,64,4): cell(p,r,6,42,7,33)
# final resolving notes and lower activity
# save
with open('/workspace/patterns.json','w') as f: json.dump(calls,f)
print(len(calls))
